'use strict';
// Shared original vertices connect at ~0.1 m coordinate precision. Interpolated
// points are private to each road, so a geometric crossing is not a junction.
function buildRoadGraph(routes,kmBetween){const nodes=[],edges=[],lookup=new Map();function node(p,shared){const key=shared?p.map(x=>x.toFixed(6)).join(','):null;if(key&&lookup.has(key))return lookup.get(key);let i=nodes.length;nodes.push({p,adj:[]});if(key)lookup.set(key,i);return i}for(const r of routes){if(r.status==='Closed'||!(r.speed>0))continue;let last=node(r.coords[0],true);for(let j=1;j<r.coords.length;j++){const a=r.coords[j-1],b=r.coords[j],steps=Math.max(1,Math.ceil(kmBetween(a,b)/.08));for(let k=1;k<=steps;k++){const p=[a[0]+(b[0]-a[0])*k/steps,a[1]+(b[1]-a[1])*k/steps],next=node(p,k===steps);if(next===last)continue;const edge={a:last,b:next,km:kmBetween(nodes[last].p,nodes[next].p),speed:r.speed,road:r,ab:r.direction!=='reverse',ba:r.direction!=='forward'};edges.push(edge);if(edge.ab)nodes[last].adj.push({to:next,edge});if(edge.ba)nodes[next].adj.push({to:last,edge});last=next}}}return{nodes,edges}}
function shortestTimes(nodes,origin,available,factor){const dist=nodes.map(()=>Infinity),heap=[];function push(item){heap.push(item);let i=heap.length-1;while(i>0){let p=(i-1)>>1;if(heap[p][0]<=item[0])break;heap[i]=heap[p];i=p}heap[i]=item}function pop(){const first=heap[0],end=heap.pop();if(heap.length){let i=0;while(true){let l=i*2+1;if(l>=heap.length)break;let r=l+1,c=r<heap.length&&heap[r][0]<heap[l][0]?r:l;if(heap[c][0]>=end[0])break;heap[i]=heap[c];i=c}heap[i]=end}return first}dist[origin]=0;push([0,origin]);while(heap.length){let [cost,u]=pop();if(cost!==dist[u])continue;if(cost>available)break;for(const a of nodes[u].adj){let next=cost+a.edge.km/(a.edge.speed*factor)*60;if(next<dist[a.to]){dist[a.to]=next;push([next,a.to])}}}return dist}
if(typeof module!=='undefined')module.exports={buildRoadGraph,shortestTimes};
